-- title: Inventory
-- description: Warehouse stock: suppliers, items, warehouses, stock levels and daily stock movements (January - June 2026).
--
-- Tables: suppliers, warehouses, items, stock_levels, stock_movements
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE suppliers (
    id      INTEGER PRIMARY KEY,
    name    TEXT NOT NULL,
    country TEXT NOT NULL,
    email   TEXT
);

CREATE TABLE warehouses (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    city     TEXT NOT NULL,
    capacity INTEGER NOT NULL
);

CREATE TABLE items (
    id            INTEGER PRIMARY KEY,
    sku           TEXT NOT NULL UNIQUE,
    name          TEXT NOT NULL,
    supplier_id   INTEGER NOT NULL REFERENCES suppliers (id),
    unit_cost     REAL NOT NULL,
    reorder_level INTEGER NOT NULL      -- order more when stock falls below this
);

CREATE TABLE stock_levels (
    item_id      INTEGER NOT NULL REFERENCES items (id),
    warehouse_id INTEGER NOT NULL REFERENCES warehouses (id),
    quantity     INTEGER NOT NULL CHECK (quantity >= 0),
    PRIMARY KEY (item_id, warehouse_id)
);

CREATE TABLE stock_movements (
    id            INTEGER PRIMARY KEY,
    item_id       INTEGER NOT NULL REFERENCES items (id),
    warehouse_id  INTEGER NOT NULL REFERENCES warehouses (id),
    movement_date TEXT NOT NULL,
    direction     TEXT NOT NULL CHECK (direction IN ('in', 'out')),
    quantity      INTEGER NOT NULL CHECK (quantity > 0),
    reason        TEXT NOT NULL
);





